import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'quote-store',
  description:
    "Price jobs and track quotes (quotes.json) at the business's own rates, tax and terms (rates.json). action:'status' for every quote with its exact total, the follow-ups due and the win/loss record; 'add' to start a quote (an existing title is updated, never duplicated); 'add_line' and 'remove_line' to price it (the script works out every amount and the tax); 'send', 'follow_up' and 'outcome' as it moves; 'set_rate' and 'set_terms' for the business's rates, tax and quote terms; 'show' for one quote line by line.",
  inputs: {
    action: {
      type: 'string',
      description:
        "One of 'status', 'add', 'add_line', 'remove_line', 'send', 'follow_up', 'outcome', 'set_rate', 'set_terms', 'show', or 'list'.",
      required: true,
    },
    id: { type: 'string', description: "Quote id, e.g. 'q-3'." },
    title: {
      type: 'string',
      description: "The job, e.g. 'Harbor Street Café kitchen rewire'. Also finds the quote (or its client) when no id is given.",
    },
    client: { type: 'string', description: 'Who the quote is for.' },
    contact: { type: 'string', description: 'The person there.' },
    site: { type: 'string', description: 'Where the work is.' },
    kind: { type: 'string', description: 'labor, materials, or other.' },
    description: { type: 'string', description: "What the line is, e.g. 'Electrician labor' or '200A panel'." },
    qty: { type: 'number', description: 'Quantity, e.g. 16 hours or 2 panels (default 1).' },
    addQty: { type: 'number', description: "Add to the quantity of the line with this description, e.g. 6 more hours." },
    unit: { type: 'string', description: 'hour, each, foot, or lot.' },
    rate: { type: 'number', description: 'Price per unit in dollars, e.g. 95.' },
    rateName: { type: 'string', description: "A saved rate by name, e.g. 'Electrician'; it fills the rate, unit and kind." },
    line: { type: 'number', description: 'Line number, for remove_line.' },
    name: { type: 'string', description: "For set_rate: the rate's name, e.g. 'Electrician'." },
    taxRate: { type: 'number', description: 'For set_terms: the sales tax percent the business charges, e.g. 8.25 (0 for none).' },
    taxOn: { type: 'string', description: 'For set_terms: materials (tax on materials only) or all (the whole quote).' },
    validDays: { type: 'number', description: 'How many days a quote stays valid after sending.' },
    followUpDays: { type: 'number', description: 'For set_terms: days after sending to follow up.' },
    followUpAt: { type: 'string', description: 'Next follow-up date, YYYY-MM-DD.' },
    inDays: { type: 'number', description: 'Next follow-up this many days from today, instead of followUpAt.' },
    outcome: { type: 'string', description: 'won or lost.' },
    note: { type: 'string', description: 'What happened or why, in the words given.' },
    withinDays: { type: 'number', description: 'How many days ahead counts for follow-ups (default 7).' },
  },
  outputs: {
    drafts: { type: 'number', description: 'Quotes still being priced.' },
    waiting: { type: 'number', description: 'Quotes sent and waiting for an answer.' },
    followUpsDue: { type: 'number', description: 'Follow-ups overdue or due today.' },
    total: { type: 'number', description: 'The total of the quote this call acted on, in dollars (0 when none).' },
    summary: { type: 'string', description: 'What changed, then the quotes picture; or one quote line by line; or the listing.' },
  },
  requires: ['workspace.read', 'workspace.write', 'reminders'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── quote-rules-start ──
// Pure derivations: money in integer cents, line amounts and quote totals that
// are exact to the cent (quantities to a thousandth, tax rates in basis
// points, both rounded half up), local calendar days for follow-ups, finding a
// quote or a line by name, and the quotes picture the crew reads. Kept
// self-contained between these sentinels so unit tests execute the shipped
// bytes.
var DAY_MS = 86400000;
var STAGES = ['draft', 'sent', 'won', 'lost'];
var KINDS = ['labor', 'materials', 'other'];
var NAME_STOP = ['the', 'and', 'for', 'with', 'our', 'quote', 'bid', 'job', 'estimate'];

function pad(n) {
  return n < 10 ? '0' + n : String(n);
}
function localDay(ms) {
  var d = new Date(ms);
  return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
}
function normalizeDate(text) {
  var raw = String(text || '').trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(raw)) return raw.slice(0, 10);
  var parsed = Date.parse(raw);
  return isFinite(parsed) ? localDay(parsed) : null;
}
function daysLeft(day, nowMs) {
  var due = Date.parse(String(day).slice(0, 10) + 'T00:00:00');
  var today = Date.parse(localDay(nowMs) + 'T00:00:00');
  return Math.round((due - today) / DAY_MS);
}
function addDays(day, n) {
  var d = new Date(String(day).slice(0, 10) + 'T12:00:00');
  d.setDate(d.getDate() + n);
  return localDay(d.getTime());
}
function when(days) {
  if (days < 0) return -days + (days === -1 ? ' day late' : ' days late');
  if (days === 0) return 'today';
  if (days === 1) return 'tomorrow';
  return 'in ' + days + ' days';
}
function cap(text) {
  return String(text).charAt(0).toUpperCase() + String(text).slice(1);
}
function ago(days) {
  return days <= 0 ? 'today' : days === 1 ? 'yesterday' : days + ' days ago';
}
// Dollars as a number or text ('$1,850', '95.50') to integer cents; null when it is not money.
function toCents(value) {
  if (typeof value === 'string') value = Number(value.replace(/[$,\s]/g, ''));
  if (typeof value !== 'number' || !isFinite(value)) return null;
  return (value < 0 ? -1 : 1) * Math.round(Math.abs(value) * 100);
}
// A quantity in thousandths, so 6.5 hours or 12.25 feet multiply exactly.
function toMilli(qty) {
  if (typeof qty === 'string') qty = Number(qty.replace(/[,\s]/g, ''));
  return typeof qty === 'number' && isFinite(qty) && qty > 0 ? Math.round(qty * 1000) : null;
}
function money(cents) {
  var n = Math.round(Number(cents) || 0);
  var abs = Math.abs(n);
  var whole = String(Math.floor(abs / 100)).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return (n < 0 ? '-$' : '$') + whole + '.' + pad(abs % 100);
}
function percent(bp) {
  return (bp / 100).toFixed(2).replace(/\.?0+$/, '') + '%';
}
function fold(text) {
  return String(text || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[‘’]/g, "'")
    .toLowerCase()
    .trim();
}
// Quantity times rate, rounded half away from zero to the cent.
function lineAmount(qtyMilli, rateCents) {
  var x = qtyMilli * rateCents;
  return (x < 0 ? -1 : 1) * Math.floor((Math.abs(x) + 500) / 1000);
}
function qtyText(qty, unit) {
  var n = Math.round(Number(qty) * 1000) / 1000;
  var u = String(unit || 'each');
  if (n === 1 || u === 'each' || u === 'lot' || /s$/.test(u)) return n + ' ' + u;
  return n + ' ' + (u === 'foot' ? 'feet' : /(x|ch|sh)$/.test(u) ? u + 'es' : u + 's');
}
function totals(lines, taxBp, taxOn) {
  var t = { labor: 0, materials: 0, other: 0, subtotal: 0, taxable: 0, tax: 0, total: 0 };
  (lines || []).forEach(function (l) {
    var a = Number(l.amountCents) || 0;
    t[KINDS.indexOf(l.kind) >= 0 ? l.kind : 'other'] += a;
    t.subtotal += a;
  });
  t.taxable = Math.max(0, taxOn === 'all' ? t.subtotal : t.materials);
  t.tax = Math.floor((t.taxable * (taxBp || 0) + 5000) / 10000);
  t.total = t.subtotal + t.tax;
  return t;
}
function quoteTotals(record) {
  var f = record.fields || {};
  return totals(f.lines, f.taxBp, f.taxOn);
}
// The fields a quote stores beside its lines, so a reader never re-adds them.
function totalFields(lines, taxBp, taxOn) {
  var t = totals(lines, taxBp, taxOn);
  return { laborCents: t.labor, materialsCents: t.materials, otherCents: t.other, subtotalCents: t.subtotal, taxCents: t.tax, totalCents: t.total };
}
function normalizeTerms(doc) {
  var d = doc && typeof doc === 'object' ? doc : {};
  var whole = function (v, fallback) {
    return typeof v === 'number' && Number.isInteger(v) && v > 0 ? v : fallback;
  };
  return {
    version: 1,
    taxBp: typeof d.taxBp === 'number' && Number.isInteger(d.taxBp) && d.taxBp >= 0 ? d.taxBp : 0,
    taxOn: d.taxOn === 'all' ? 'all' : 'materials',
    validDays: whole(d.validDays, 30),
    followUpDays: whole(d.followUpDays, 5),
    rates: (Array.isArray(d.rates) ? d.rates : []).filter(function (r) {
      return r && typeof r.name === 'string' && typeof r.rateCents === 'number' && Number.isInteger(r.rateCents);
    }),
  };
}
function rateText(r) {
  return r.name + ' ' + money(r.rateCents) + '/' + r.unit + ' (' + r.kind + ')';
}
function findRate(rates, name) {
  var wanted = fold(name);
  if (!wanted) return null;
  var exact = rates.filter(function (r) { return fold(r.name) === wanted; });
  if (exact.length) return exact[0];
  var partial = rates.filter(function (r) { return fold(r.name).indexOf(wanted) >= 0 || wanted.indexOf(fold(r.name)) >= 0; });
  return partial.length === 1 ? partial[0] : null;
}
function lineText(l) {
  return '#' + l.n + ' ' + l.description + ', ' + qtyText(l.qty, l.unit) + ' x ' + money(l.rateCents) + ' = ' + money(l.amountCents) + ' (' + l.kind + ')';
}
// Add a line, or change the one with the same description. Returns the new
// list and what changed; the caller re-totals.
function upsertLine(lines, input, terms) {
  var list = (lines || []).map(function (l) { return Object.assign({}, l); });
  var saved = input.rateName ? findRate(terms.rates, input.rateName) : null;
  if (input.rateName && !saved) {
    throw new Error(
      "No saved rate named '" + input.rateName + "'. Saved rates: " +
        (terms.rates.map(rateText).join(', ') || 'none yet; pass rate in dollars') + '.',
    );
  }
  var description = String(input.description || (saved && saved.name) || '').trim();
  if (!description) throw new Error("add_line needs 'description', e.g. 'Electrician labor' or '200A panel'.");
  var existing = list.filter(function (l) { return fold(l.description) === fold(description); })[0] || null;
  if (!existing && !saved && (input.rate === undefined || input.rate === null || input.rate === '')) saved = findRate(terms.rates, description);
  var rateCents =
    input.rate !== undefined && input.rate !== null && input.rate !== ''
      ? toCents(input.rate)
      : saved ? saved.rateCents : existing ? existing.rateCents : null;
  if (rateCents === null) {
    throw new Error(
      "'" + description + "' needs 'rate' (dollars per unit) or 'rateName'" +
        (terms.rates.length ? ' from the saved rates: ' + terms.rates.map(rateText).join(', ') : '') + '.',
    );
  }
  var kind = KINDS.indexOf(input.kind) >= 0 ? input.kind : saved ? saved.kind : existing ? existing.kind : 'other';
  if (rateCents < 0 && kind !== 'other') throw new Error('Only an "other" line can be a credit with a negative rate.');
  var unit = input.unit ? String(input.unit).trim() : saved ? saved.unit : existing ? existing.unit : 'each';
  var add = input.addQty !== undefined && input.addQty !== null && input.addQty !== '' ? toMilli(input.addQty) : null;
  var set = input.qty !== undefined && input.qty !== null && input.qty !== '' ? toMilli(input.qty) : null;
  if (add === null && input.addQty !== undefined && input.addQty !== null && input.addQty !== '') throw new Error('addQty must be a positive number.');
  if (set === null && input.qty !== undefined && input.qty !== null && input.qty !== '') throw new Error('qty must be a positive number.');
  var before = existing ? Math.round(existing.qty * 1000) : 0;
  var qtyMilli = add !== null ? before + add : set !== null ? set : existing ? before : 1000;
  var line = { description: existing ? existing.description : description, kind: kind, qty: qtyMilli / 1000, unit: unit, rateCents: rateCents, amountCents: lineAmount(qtyMilli, rateCents) };
  if (existing) Object.assign(existing, line);
  else list.push(line);
  list.forEach(function (l, i) { l.n = i + 1; });
  var placed = existing || list[list.length - 1];
  return {
    lines: list,
    note:
      (existing ? 'Updated line ' : 'Added line ') + lineText(placed) +
      (existing && add !== null ? ' (' + before / 1000 + ' + ' + add / 1000 + ')' : '') + '.',
  };
}
function removeLine(lines, input) {
  var list = (lines || []).map(function (l) { return Object.assign({}, l); });
  var hit = null;
  if (input.line !== undefined && input.line !== null && input.line !== '') {
    hit = list.filter(function (l) { return l.n === Number(input.line); })[0] || null;
  } else if (input.description) {
    var wanted = fold(input.description);
    var exact = list.filter(function (l) { return fold(l.description) === wanted; });
    var partial = list.filter(function (l) { return fold(l.description).indexOf(wanted) >= 0; });
    hit = exact[0] || (partial.length === 1 ? partial[0] : null);
  }
  if (!hit) {
    throw new Error(
      "Name the line by 'line' number or 'description'. Lines: " + (list.map(lineText).join('; ') || 'none') + '.',
    );
  }
  var rest = list.filter(function (l) { return l !== hit; });
  rest.forEach(function (l, i) { l.n = i + 1; });
  return { lines: rest, note: 'Removed ' + hit.description + ' (' + money(hit.amountCents) + ').' };
}
function isOpen(record) {
  return record.status === 'draft' || record.status === 'sent';
}
// The quote a person means: its id, its exact title, a title or client that
// contains what they wrote, or one whose name holds every word they used.
// Several matches prefer the open quotes; a tie is an error that names them.
function findQuote(records, input) {
  if (input.id) {
    var byId = records.filter(function (r) { return r.id === String(input.id).trim(); });
    if (byId.length) return byId[0];
    if (!input.title && !input.client) throw new Error("No quote '" + input.id + "'. " + roll(records));
  }
  var wanted = fold(input.title || input.client);
  if (!wanted) throw new Error("Pass 'id' (e.g. 'q-3') or the quote's 'title'. " + roll(records));
  var name = function (r) { return fold(r.fields.title); };
  var both = function (r) { return name(r) + ' ' + fold(r.fields.client); };
  var words = wanted.split(/[^a-z0-9']+/).filter(function (w) { return w.length > 2 && NAME_STOP.indexOf(w) < 0; });
  var tiers = [
    function (r) { return name(r) === wanted; },
    function (r) { return name(r).indexOf(wanted) >= 0 || fold(r.fields.client) === wanted; },
    function (r) {
      return words.length > 0 && words.every(function (w) { return both(r).indexOf(w) >= 0 || both(r).indexOf(w.replace(/s$/, '')) >= 0; });
    },
  ];
  for (var i = 0; i < tiers.length; i++) {
    var hits = records.filter(tiers[i]);
    if (hits.length > 1) {
      var open = hits.filter(isOpen);
      if (open.length) hits = open;
    }
    if (hits.length === 1) return hits[0];
    if (hits.length > 1) {
      throw new Error(
        "More than one quote matches '" + (input.title || input.client) + "': " +
          hits.map(function (r) { return r.id + ' ' + r.fields.title; }).join(', ') + '. Pass id.',
      );
    }
  }
  throw new Error("No quote matches '" + (input.title || input.client) + "'. " + roll(records));
}
function roll(records) {
  return records.length
    ? 'Quotes: ' + records.map(function (r) { return r.id + ' ' + r.fields.title + ' (' + r.status + ')'; }).join(', ') + '.'
    : 'There are no quotes yet.';
}
function lastNote(record) {
  var notes = (record.history || []).filter(function (h) { return h.note; });
  return notes.length ? notes[notes.length - 1].note : '';
}
function quoteLine(record, nowMs) {
  var f = record.fields || {};
  var t = quoteTotals(record);
  var lines = (f.lines || []).length;
  var head =
    record.id + (f.client && fold(f.title).indexOf(fold(f.client)) < 0 ? ', ' + f.client : '') + ', ' + record.status + ', ' +
    lines + (lines === 1 ? ' line' : ' lines') + ', total ' + money(t.total) + (t.tax ? ' with ' + money(t.tax) + ' tax' : '');
  var parts = [head];
  if (record.status === 'sent') {
    if (f.sentAt) parts.push('sent ' + ago(-daysLeft(f.sentAt, nowMs)));
    if (f.followUpAt) parts.push('follow up ' + when(daysLeft(f.followUpAt, nowMs)) + ' (' + f.followUpAt + ')');
    if (f.validUntil) parts.push((daysLeft(f.validUntil, nowMs) < 0 ? 'expired ' : 'valid until ') + f.validUntil);
  }
  if (!isOpen(record) && f.closedAt) parts.push(record.status + ' ' + f.closedAt + (f.reason ? ': ' + f.reason : ''));
  return f.title + ' (' + parts.join('; ') + ')';
}
function followLine(record, nowMs) {
  var f = record.fields;
  var note = lastNote(record).replace(/[.\s]+$/, '');
  return (
    f.title + ' (' + record.id + (f.contact ? ', ' + f.contact : '') + ', ' + money(quoteTotals(record).total) +
    (f.sentAt ? ', sent ' + ago(-daysLeft(f.sentAt, nowMs)) : '') + ') ' + when(daysLeft(f.followUpAt, nowMs)) +
    (note && note !== 'Sent to the client' ? '; last note: ' + note : '')
  );
}
function picture(records, terms, nowMs, withinDays) {
  var byStatus = function (s) { return records.filter(function (r) { return r.status === s; }); };
  var drafts = byStatus('draft');
  var sent = byStatus('sent');
  var won = byStatus('won');
  var lost = byStatus('lost');
  var total = function (list) { return list.reduce(function (t, r) { return t + quoteTotals(r).total; }, 0); };
  var due = sent
    .filter(function (r) { return r.fields.followUpAt && daysLeft(r.fields.followUpAt, nowMs) <= withinDays; })
    .sort(function (a, b) { return String(a.fields.followUpAt).localeCompare(String(b.fields.followUpAt)); });
  var dueNow = due.filter(function (r) { return daysLeft(r.fields.followUpAt, nowMs) <= 0; });
  var recentFirst = function (list) {
    return list.slice().sort(function (a, b) { return String(b.fields.closedAt || '').localeCompare(String(a.fields.closedAt || '')); });
  };
  var parts = [
    records.length + (records.length === 1 ? ' quote: ' : ' quotes: ') + drafts.length + ' draft, ' + sent.length +
      ' sent and waiting (' + money(total(sent)) + '), ' + won.length + ' won, ' + lost.length + ' lost.',
  ];
  // One list, overdue first: a model asked what needs chasing reads a separate late list as out of scope.
  parts.push(
    due.length
      ? 'Follow-ups within ' + withinDays + ' days, overdue first: ' + due.map(function (r) { return followLine(r, nowMs); }).join(' | ') + '.'
      : 'No follow-ups due in the next ' + withinDays + ' days.',
  );
  if (drafts.length) parts.push('Drafts: ' + drafts.map(function (r) { var ls = r.fields.lines || []; return quoteLine(r, nowMs) + (ls.length ? ': ' + ls.map(lineText).join('; ') : ''); }).join(' | ') + '.');
  if (sent.length) parts.push('Sent and waiting: ' + sent.map(function (r) { return quoteLine(r, nowMs); }).join(' | ') + '.');
  if (won.length) parts.push('Won (latest first): ' + recentFirst(won).slice(0, 5).map(function (r) { return quoteLine(r, nowMs); }).join(' | ') + '.');
  if (lost.length) parts.push('Lost (latest first): ' + recentFirst(lost).slice(0, 5).map(function (r) { return quoteLine(r, nowMs); }).join(' | ') + '.');
  if (won.length + lost.length) {
    var decided = total(won) + total(lost);
    parts.push(
      'Win rate: ' + won.length + ' of ' + (won.length + lost.length) + ' decided quotes (' + Math.round((won.length / (won.length + lost.length)) * 100) + '%), ' +
        money(total(won)) + ' of ' + money(decided) + ' by value.',
    );
  }
  parts.push(
    'Tax: ' + (terms.taxBp ? percent(terms.taxBp) + ' on ' + (terms.taxOn === 'all' ? 'the whole quote' : 'materials') : 'none set') +
      '. Quotes stay valid ' + terms.validDays + ' days; follow up ' + terms.followUpDays + ' days after sending. Saved rates: ' +
      (terms.rates.map(rateText).join(', ') || 'none yet') + '.',
  );
  return {
    drafts: drafts.length,
    waiting: sent.length,
    followUpsDue: dueNow.length,
    summary: parts.join(' '),
  };
}
// One quote line by line, for the person to read or the crew to quote exactly.
function detail(record, nowMs) {
  var f = record.fields || {};
  var t = quoteTotals(record);
  var rows = (f.lines || []).map(lineText);
  return [
    f.title + ' (' + record.id + ', ' + record.status + (f.client ? ', for ' + f.client : '') + (f.site ? ' at ' + f.site : '') + ').',
    rows.length ? 'Lines: ' + rows.join('; ') + '.' : 'No lines yet.',
    'Labor ' + money(t.labor) + ', materials ' + money(t.materials) + (t.other ? ', other ' + money(t.other) : '') +
      '. Subtotal ' + money(t.subtotal) + '. Tax ' + money(t.tax) +
      (f.taxBp ? ' (' + percent(f.taxBp) + ' on ' + (f.taxOn === 'all' ? 'the whole quote' : 'materials ' + money(t.materials)) + ')' : ' (no tax set)') +
      '. Total ' + money(t.total) + '.',
    record.status === 'sent'
      ? 'Sent ' + f.sentAt + (f.followUpAt ? '; follow up ' + when(daysLeft(f.followUpAt, nowMs)) + ' (' + f.followUpAt + ')' : '') +
        (f.validUntil ? '; valid until ' + f.validUntil : '') + '.'
      : !isOpen(record) && f.closedAt
        ? cap(record.status) + ' ' + f.closedAt + (f.reason ? ': ' + f.reason : '') + '.'
        : '',
  ]
    .filter(Boolean)
    .join(' ');
}
// ── quote-rules-end ──

type Quote = { id: string; status: string; fields: Record<string, unknown>; history?: Array<{ note?: string }> };
type Line = Record<string, unknown>;

const quotes = rosterStore(gezel.fs, 'quotes.json', { stages: ['draft', 'sent', 'won', 'lost'], idPrefix: 'q' });
const now = Date.now();
const today = localDay(now);

function given(value: unknown): boolean {
  return value !== undefined && value !== null && value !== '';
}

async function readTerms(): Promise<ReturnType<typeof normalizeTerms>> {
  let raw: string | null = null;
  try {
    raw = await gezel.fs.read('rates.json');
  } catch {
    raw = null;
  }
  if (raw === null) return normalizeTerms(null);
  try {
    return normalizeTerms(JSON.parse(raw));
  } catch {
    throw new Error('rates.json is not valid JSON. Fix or remove it; it will not be overwritten automatically.');
  }
}

async function writeTerms(terms: ReturnType<typeof normalizeTerms>): Promise<void> {
  await gezel.fs.write('rates.json', JSON.stringify(terms, null, 2) + '\n');
}

function followUpInput(): string | undefined {
  if (typeof input.inDays === 'number' && isFinite(input.inDays)) return addDays(today, Math.max(0, Math.round(input.inDays)));
  if (given(input.followUpAt)) {
    const day = normalizeDate(input.followUpAt);
    if (!day) throw new Error("followUpAt must be a date, e.g. '2026-11-20', or pass inDays.");
    return day;
  }
  return undefined;
}

function wholeDays(value: unknown, label: string): number | undefined {
  if (!given(value)) return undefined;
  const n = Number(value);
  if (!isFinite(n) || n < 1 || n > 365) throw new Error(label + ' is a number of days from 1 to 365.');
  return Math.round(n);
}

// Lines change only on an open quote; a sent one goes back to draft so the
// client is never holding a price the register no longer shows.
async function reprice(record: Quote, lines: Line[], what: string): Promise<string> {
  const f = record.fields;
  const title = String(f.title);
  if (!isOpen(record)) throw new Error(title + ' is ' + record.status + '; its price is settled. Start a new quote for more work.');
  await quotes.update(record.id, { fields: { lines, ...totalFields(lines, f.taxBp, f.taxOn) } });
  let tail = '';
  if (record.status === 'sent') {
    await quotes.update(record.id, { fields: { followUpAt: null } });
    await quotes.transition(record.id, 'draft', { note: 'Revised after sending: ' + what });
    tail = ' It had been sent, so it is back in draft: send it again when the client should see the new price.';
  }
  return what + ' ' + title + ' total now ' + money(totals(lines, f.taxBp, f.taxOn).total) + '.' + tail;
}

// The quotes' one reminder sits on the soonest follow-up, the morning it is due.
async function remindNextFollowUp(): Promise<void> {
  const next = (await quotes.list())
    .filter((r) => r.status === 'sent' && typeof r.fields.followUpAt === 'string')
    .map((r) => ({ record: r, at: Date.parse(String(r.fields.followUpAt) + 'T09:00:00') }))
    .filter((r) => r.at > now)
    .sort((a, b) => a.at - b.at)[0];
  try {
    if (!next || next.at - now > 30 * DAY_MS) await gezel.reminder.clear();
    else {
      const f = next.record.fields;
      await gezel.reminder.set({
        at: new Date(next.at).toISOString(),
        title: ('Follow up on the quote for ' + String(f.client || f.title)).slice(0, 80),
        body: (String(f.title) + ', ' + money(quoteTotals(next.record).total) + ', sent ' + String(f.sentAt) + '.').slice(0, 160),
      });
    }
  } catch {
    // Reminders are a convenience; the quotes are the record.
  }
}

const withinDays = typeof input.withinDays === 'number' && input.withinDays > 0 ? Math.round(input.withinDays) : 7;
let note = '';
let acted: string | null = null;
let shown = '';

if (input.action === 'add') {
  const all = (await quotes.list()) as Quote[];
  const title = String(input.title || input.client || '').trim();
  let existing: Quote | null = null;
  if (given(input.id)) existing = findQuote(all, { id: input.id, title: input.title });
  else if (title) existing = all.find((r) => fold(r.fields.title) === fold(title)) ?? null;
  if (!existing && !title) throw new Error("add needs 'title': the job, e.g. 'Maple Row panel upgrade'.");
  const fields: Record<string, unknown> = {};
  if (input.client) fields.client = input.client.trim();
  if (input.contact) fields.contact = input.contact.trim();
  if (input.site) fields.site = input.site.trim();
  if (input.note) fields.note = input.note.trim();
  if (existing) {
    if (given(input.id) && input.title && fold(input.title) !== fold(existing.fields.title)) fields.title = input.title.trim();
    await quotes.update(existing.id, { fields });
    acted = existing.id;
    note = 'Updated ' + String(existing.fields.title) + '.';
  } else {
    const terms = await readTerms();
    const record = await quotes.add({
      status: 'draft',
      fields: { title, ...fields, lines: [], taxBp: terms.taxBp, taxOn: terms.taxOn, ...totalFields([], terms.taxBp, terms.taxOn) },
    });
    acted = record.id;
    note = 'Started ' + record.id + ': ' + title + ' (draft). Add its lines next.';
  }
} else if (input.action === 'add_line' || input.action === 'remove_line') {
  const record = findQuote((await quotes.list()) as Quote[], input);
  const lines = (record.fields.lines ?? []) as Line[];
  const change = input.action === 'add_line' ? upsertLine(lines, input, await readTerms()) : removeLine(lines, input);
  note = await reprice(record, change.lines, change.note);
  acted = record.id;
} else if (input.action === 'send') {
  const record = findQuote((await quotes.list()) as Quote[], input);
  const title = String(record.fields.title);
  acted = record.id;
  if (record.status === 'sent') note = title + ' was already sent on ' + String(record.fields.sentAt) + '.';
  else if (!isOpen(record)) throw new Error(title + ' is ' + record.status + '; it cannot be sent again.');
  else {
    if (!((record.fields.lines ?? []) as Line[]).length) throw new Error(title + ' has no lines yet; add them before sending.');
    const terms = await readTerms();
    const validUntil = addDays(today, wholeDays(input.validDays, 'validDays') ?? terms.validDays);
    const follow = followUpInput() ?? addDays(today, terms.followUpDays);
    await quotes.update(record.id, { fields: { sentAt: today, validUntil, followUpAt: follow } });
    await quotes.transition(record.id, 'sent', { note: input.note || 'Sent to the client.' });
    note = 'Sent ' + title + ', total ' + money(quoteTotals(record).total) + '. Valid until ' + validUntil + '; first follow-up ' + follow + '.';
  }
} else if (input.action === 'follow_up') {
  const record = findQuote((await quotes.list()) as Quote[], input);
  const title = String(record.fields.title);
  if (record.status !== 'sent') {
    throw new Error(title + ' is ' + record.status + (record.status === 'draft' ? '; send it before following up.' : '; it is closed.'));
  }
  const next = followUpInput() ?? addDays(today, (await readTerms()).followUpDays);
  await quotes.update(record.id, { fields: { followUpAt: next, lastFollowUpAt: today }, note: input.note || 'Followed up.' });
  acted = record.id;
  note = 'Logged the follow-up on ' + title + (input.note ? ': ' + input.note.trim() : '') + '. Next follow-up ' + next + '.';
} else if (input.action === 'outcome') {
  const outcome = String(input.outcome || '').trim().toLowerCase();
  if (outcome !== 'won' && outcome !== 'lost') throw new Error("outcome needs 'outcome': won or lost.");
  const record = findQuote((await quotes.list()) as Quote[], input);
  const title = String(record.fields.title);
  acted = record.id;
  if (record.status === outcome) note = title + ' is already ' + outcome + '.';
  else if (!isOpen(record)) throw new Error(title + ' is already ' + record.status + '.');
  else {
    await quotes.update(record.id, { fields: { closedAt: today, followUpAt: null, ...(input.note ? { reason: input.note.trim() } : {}) } });
    await quotes.transition(record.id, outcome, { note: input.note || (outcome === 'won' ? 'Won.' : 'Lost.') });
    note = (outcome === 'won' ? 'Won ' : 'Lost ') + title + ', ' + money(quoteTotals(record).total) + (input.note ? ' (' + input.note.trim() + ')' : '') + '.';
  }
} else if (input.action === 'set_rate') {
  const name = String(input.name || input.description || '').trim();
  if (!name) throw new Error("set_rate needs 'name', e.g. 'Electrician'.");
  const rateCents = toCents(input.rate);
  if (rateCents === null || rateCents < 0) throw new Error("set_rate needs 'rate' in dollars per unit, e.g. 95.");
  const kind = KINDS.indexOf(String(input.kind)) >= 0 ? String(input.kind) : 'labor';
  const unit = input.unit ? input.unit.trim() : kind === 'labor' ? 'hour' : 'each';
  const terms = await readTerms();
  const at = terms.rates.findIndex((r) => fold(r.name) === fold(name));
  const rate = { name, kind, unit, rateCents };
  if (at >= 0) terms.rates[at] = rate;
  else terms.rates.push(rate);
  await writeTerms(terms);
  note = (at >= 0 ? 'Updated the rate ' : 'Saved the rate ') + rateText(rate) + '. Lines already on quotes keep their price; new lines use this one.';
} else if (input.action === 'set_terms') {
  const terms = await readTerms();
  let changed = false;
  if (given(input.taxRate)) {
    const p = Number(String(input.taxRate).replace('%', ''));
    if (!isFinite(p) || p < 0 || p > 50) throw new Error('taxRate is a percent, e.g. 8.25 (0 for none).');
    terms.taxBp = Math.round(p * 100);
    changed = true;
  }
  if (given(input.taxOn)) {
    const on = String(input.taxOn).trim().toLowerCase();
    if (on !== 'materials' && on !== 'all') throw new Error('taxOn is materials or all.');
    terms.taxOn = on;
    changed = true;
  }
  const valid = wholeDays(input.validDays, 'validDays');
  if (valid !== undefined) terms.validDays = valid;
  const follow = wholeDays(input.followUpDays, 'followUpDays');
  if (follow !== undefined) terms.followUpDays = follow;
  if (!changed && valid === undefined && follow === undefined) throw new Error('set_terms needs taxRate, taxOn, validDays or followUpDays.');
  await writeTerms(terms);
  // Drafts follow the business's tax; sent and closed quotes keep the tax they went out with.
  const drafts = (await quotes.list()).filter((r) => r.status === 'draft');
  for (const d of drafts) {
    await quotes.update(d.id, {
      fields: { taxBp: terms.taxBp, taxOn: terms.taxOn, ...totalFields((d.fields.lines ?? []) as Line[], terms.taxBp, terms.taxOn) },
    });
  }
  note =
    'Tax is ' + (terms.taxBp ? percent(terms.taxBp) + ' on ' + (terms.taxOn === 'all' ? 'the whole quote' : 'materials') : 'not charged') +
    '; quotes stay valid ' + terms.validDays + ' days; follow up ' + terms.followUpDays + ' days after sending.' +
    (drafts.length ? ' Re-totaled ' + drafts.length + (drafts.length === 1 ? ' draft' : ' drafts') + '; sent quotes keep the tax they went out with.' : '');
} else if (input.action === 'show') {
  const record = findQuote((await quotes.list()) as Quote[], input);
  acted = record.id;
  shown = detail(record, now);
} else if (input.action !== 'status' && input.action !== 'list') {
  throw new Error(
    "Unknown action '" + input.action + "'. Use status, add, add_line, remove_line, send, follow_up, outcome, set_rate, set_terms, show, or list.",
  );
}

const records = (await quotes.list()) as Quote[];
const view = picture(records, await readTerms(), now, withinDays);
const touched = acted ? records.find((r) => r.id === acted) : undefined;
await remindNextFollowUp();

gezel.output({
  drafts: view.drafts,
  waiting: view.waiting,
  followUpsDue: view.followUpsDue,
  total: touched ? quoteTotals(touched).total / 100 : 0,
  summary: shown
    ? shown
    : input.action === 'list'
      ? records.map((r) => '[' + r.status + '] ' + quoteLine(r, now)).join('\n') || 'There are no quotes yet.'
      : (note ? note + ' ' : '') + view.summary,
});

